new_data_reward_daily_close_service_v1<-function(project_root,context){python<-Sys.which('python3');cli<-file.path(normalizePath(project_root),'scripts','desktop_reward_daily_close.py');space<-runtime_data_space_path(context);ctx<-list(tenant_id=context$tenant_id,user_id=context$user_id,data_space_id=context$data_space_id,actor_id=context$actor_id);cache<-new.env(parent=emptyenv());run<-function(cmd,p){o<-suppressWarnings(system2(python,c('-B','-E','-s',shQuote(cli),cmd),stdout=TRUE,stderr=TRUE,input=as.character(jsonlite::toJSON(p,auto_unbox=TRUE,null='null'))));x<-tryCatch(jsonlite::fromJSON(tail(o,1),simplifyVector=FALSE),error=function(e)NULL);if(is.null(x)||!identical(x$status,'completed'))stop(structure(list(message=if(is.null(x$code))'data_reward_daily_close_boundary_failed'else x$code,call=NULL,code=if(is.null(x$code))'data_reward_daily_close_boundary_failed'else x$code),class=c('spot_data_reward_daily_close_error','error','condition')));x$result};preview<-function(draft_ref){x<-run('preview',list(space=space,context=ctx,draft_ref=draft_ref));assign(draft_ref,x,cache);x$public_preview};apply<-function(draft_ref,confirmed,now){x<-get(draft_ref,cache);run('apply',list(space=space,context=ctx,draft_ref=draft_ref,draft_revision=x$draft_revision,candidate=x$trusted_candidate,confirmed=confirmed,updated_at_utc=now))};list(preview=preview,apply=apply)}
